import { useContext, useState, useEffect } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { AppContext } from "../../../AppContext";

export default function EditProduct() {


    const params = useParams()
    const [initialData, setInitialData]= useState()
    const [validationErrors, setValidationErrors] = useState({})
    const { userCredentials, setUserCredentials } = useContext(AppContext)
    const navigate = useNavigate()
    const baseUrl = (process.env.REACT_APP_API_BASE_URL || "http://localhost:4000") + "/products/";

    function getProduct(){
   	 fetch(baseUrl + params.id)
    	.then(response =>{
           if(response.ok){
		return response.json()
	   }
	   throw new Error()
	})
        .then(data => {
            setInitialData(data)
	})
	.catch(error => {
            alert("Unable to read product details.")

	})
    }

    useEffect(getProduct, [])

    async function handleSubmit(event) {
        event.preventDefault()

        const formData = new FormData(event.target)
        const product = Object.fromEntries(formData.entries())

        if (!product.name || !product.brand || !product.category || !product.price
            || !product.description) {

            alert("Please fill all the fields!")
            return
        }

        try {
            const response = await fetch(baseUrl+ params.id, {
                method: "PATCH",
                headers: {
                    "Authorization": "Bearer " + userCredentials.accessToken
                },
                body: formData
            })

            const data = await response.json()

            if (response.ok) {
                // Product created correctly!
                navigate("/admin/products")
            }
	        // These else-if statements read error status's and provide reponses	
            else if (response.status === 400) {
                setValidationErrors(data)// response show error  
            }
            else if (response.status === 401) {
                // Disconnect the user  
               setUserCredentials(null)// this is the bouncer else-if. If you don't got the credentials you don't get in!
            }
            else {
                alert("Unable to Update the product!")
            }
        }
        catch (error) {
            alert("Unable to connect to the server!")
        }
    }

    return (
        <div className="container my-4">
            <div className="row">
                <div className="col-md-8 mx-auto rounded border p-4">
                    <h2 className="text-center mb-5">Edit Product</h2>

                    <div className="row mb-3">
                        <label className="col-sm-4 col-form-label">ID</label>
                        <div className="col-sm-8">
                            <input readOnly className="form-control-plaintext" defaultValue={params.id} />
                        </div>
                    </div>

                    {
                        initialData && // This conditional makes where if we have prod details we display
			               // Otherwise we don't display the form
                        <form onSubmit={handleSubmit}>
                            <div className="row mb-3">
                                <label className="col-sm-4 col-form-label">Name</label>
                                <div className="col-sm-8">
                                    <input className="form-control" name="name" defaultValue={initialData.name} />
                                    <span className="text-danger">{validationErrors.name}</span>
                                </div>
                            </div>

                            <div className="row mb-3">
                                <label className="col-sm-4 col-form-label">Brand</label>
                                <div className="col-sm-8">
                                    <input className="form-control" name="brand" defaultValue={initialData.brand} />
                                    <span className="text-danger">{validationErrors.brand}</span>
                                </div>
                            </div>

                            <div className="row mb-3">
                                <label className="col-sm-4 col-form-label">Category</label>
                                <div className="col-sm-8">
                                    <select className="form-select" name="category" defaultValue={initialData.category}>
                                        <option value='Other'>Other</option>
                                        <option value='Phones'>Phones</option>
                                        <option value='Computers'>Computers</option>
                                        <option value='Accessories'>Accessories</option>
                                        <option value='Printers'>Printers</option>
                                        <option value='Cameras'>Cameras</option>
                                    </select>
                                    <span className="text-danger">{validationErrors.category}</span>
                                </div>
                            </div>

                            <div className="row mb-3">
                                <label className="col-sm-4 col-form-label">Price</label>
                                <div className="col-sm-8">
                                    <input className="form-control" name="price" type="number" step="0.01" min="1"
                                        defaultValue={initialData.price} />
                                    <span className="text-danger">{validationErrors.price}</span>
                                </div>
                            </div>

                            <div className="row mb-3">
                                <label className="col-sm-4 col-form-label">Description</label>
                                <div className="col-sm-8">
                                    <textarea className="form-control" name="description" rows="4"
                                        defaultValue={initialData.description} />
                                    <span className="text-danger">{validationErrors.description}</span>
                                </div>
                            </div>

                            <div className="row mb-3">
                                <div className="offset-sm-4 col-sm-8">
                                    <img src={"http://localhost:4000/images/" + initialData.imageFilename}
                                        width="150" alt="..." />
                                </div>
                            </div>

                            <div className="row mb-3">
                                <label className="col-sm-4 col-form-label">Image</label>
                                <div className="col-sm-8">
                                    <input className="form-control" type="file" name="image" />
                                    <span className="text-danger">{validationErrors.image}</span>
                                </div>
                            </div>

                            <div className="row mb-3">
                                <label className="col-sm-4 col-form-label">Created At</label>
                                <div className="col-sm-8">
                                    <input readOnly className="form-control-plaintext"
                                        defaultValue={initialData.createdAt.slice(0, 10)} />
                                </div>
                            </div>

                            <div className="row">
                                <div className="offset-sm-4 col-sm-4 d-grid">
                                    <button type="submit" className="btn btn-primary">Submit</button>
                                </div>
                                <div className="col-sm-4 d-grid">
                                    <Link className="btn btn-secondary" to='/admin/products' role="button">Cancel</Link>
                                </div>
                            </div>

                        </form>
                    }
                </div>
            </div>
        </div>
    )
}
